    12→  requires is_connection<Connection>
    13→Result<Ref<Connection>> create_table_impl(const Ref<Connection>& _conn,
    14→                                          const bool _if_not_exists) {
    15→  const auto query = transpilation::to_create_table<ValueType>(_if_not_exists);
    16→  return _conn->execute(_conn->to_sql(query)).transform([&](const auto&) {
    17→    return _conn;
    18→  });
