   100→Result<Ref<IteratorBase>> Connection::read_impl(
   101→    const dynamic::SelectFrom& _query) {
   102→  const auto sql = to_sql_impl(_query);
   103→
   104→  sqlite3_stmt* p_stmt = nullptr;
   105→
   106→  sqlite3_prepare(conn_.get(), /* Database handle */
   107→                  sql.c_str(), /* SQL statement, UTF-8 encoded */
   108→                  sql.size(),  /* Maximum length of zSql in bytes. */
   109→                  &p_stmt,     /* OUT: Statement handle */
   110→                  nullptr      /* OUT: Pointer to unused portion of zSql */
   111→  );
   112→
   113→  if (!p_stmt) {
   114→    return error(sqlite3_errmsg(conn_.get()));
   115→  }
   116→
   117→  return Ref<sqlite3_stmt>::make(StmtPtr(p_stmt, &sqlite3_finalize))
   118→      .transform([&](auto _stmt) -> Ref<IteratorBase> {
   119→        return Ref<Iterator>::make(_stmt, conn_);
   120→      });
   121→}
   122→
   123→Result<Connection::StmtPtr> Connection::prepare_statement(
   124→    const std::string& _sql) const noexcept {
   125→  sqlite3_stmt* p_stmt = nullptr;
   126→
   127→  sqlite3_prepare(conn_.get(),  /* Database handle */
   128→                  _sql.c_str(), /* SQL statement, UTF-8 encoded */
   129→                  _sql.size(),  /* Maximum length of zSql in bytes. */
   130→                  &p_stmt,      /* OUT: Statement handle */
   131→                  nullptr       /* OUT: Pointer to unused portion of zSql */
   132→  );
   133→
   134→  if (!p_stmt) {
   135→    return error("Preparing the following statement failed: " + _sql +
   136→                 " Reason: " + sqlite3_errmsg(conn_.get()));
   137→  }
   138→
   139→  return StmtPtr(p_stmt, &sqlite3_finalize);
   140→}
