   142→Result<Nothing> Connection::rollback() noexcept { return execute("ROLLBACK;"); }
   143→
   144→Result<Nothing> Connection::start_write(const dynamic::Write& _stmt) {
   145→  if (stmt_) {
   146→    return error(
   147→        "A write operation has already been launched. You need to call "
   148→        ".end_write() before you can start another.");
   149→  }
   150→
   151→  const auto sql = to_sql_impl(_stmt);
   152→
   153→  return prepare_statement(sql)
   154→      .transform([&](auto&& _stmt) {
   155→        stmt_ = std::move(_stmt);
   156→        return Nothing{};
   157→      })
   158→      .and_then([&](const auto&) { return begin_transaction(); });
   159→}
   160→
   161→Result<Nothing> Connection::write_impl(
   162→    const std::vector<std::vector<std::optional<std::string>>>& _data) {
   163→  if (!stmt_) {
   164→    return error(
   165→        " You need to call .start_write(...) before you can call "
   166→        ".write(...).");
   167→  }
   168→
   169→  return actual_insert(_data, stmt_.get())
   170→      .or_else([&](const auto& err) -> Result<Nothing> {
   171→        rollback();
   172→        return error(err.what());
   173→      });
   174→}
   175→
   176→Result<Nothing> Connection::end_write() {
   177→  if (!stmt_) {
   178→    return error(
   179→        " You need to call .start_write(...) before you can call "
   180→        ".end_write().");
   181→  }
   182→  stmt_ = nullptr;
   183→  return commit().or_else([&](const auto& err) -> Result<Nothing> {
   184→    rollback();
   185→    return error(err.what());
   186→  });
   187→}
