    11→namespace sqlgen {
    12→
    13→template <rfl::internal::StringLiteral _new_name>
    14→struct As {
    15→  template <class ValueType>
    16→  auto operator()(const ValueType& _val) const noexcept {
    17→    if constexpr (requires(ValueType v) { v.template as<"new_name">(); }) {
    18→      return _val.template as<_new_name>();
    19→    } else {
    20→      return transpilation::As<std::remove_cvref_t<ValueType>, _new_name>{
    21→          .val = _val};
    22→    }
    23→  }
    24→
    25→  auto operator()(const char* _val) const noexcept {
    26→    return transpilation::As<std::string, _new_name>{.val = _val};
    27→  }
    28→};
    29→
    30→template <class ValueType, rfl::internal::StringLiteral _new_name>
    31→auto operator|(const ValueType& _val, const As<_new_name>& _as) {
    32→  return _as(_val);
    33→}
    34→
    35→template <rfl::internal::StringLiteral _new_name>
    36→const auto as = As<_new_name>{};
    37→
    38→}  // namespace sqlgen
    39→
