    18→template <class Connection>
    19→class Session {
    20→ public:
    21→  using ConnPtr = Ref<Connection>;
    22→
    23→  Session(const Ref<Connection>& _conn, const Ref<std::atomic_flag>& _flag)
    24→      : conn_(_conn), flag_(_flag.ptr()) {}
    25→
    26→  Session(const Session<Connection>& _other) = delete;
    27→
    28→  Session(Session<Connection>&& _other)
    29→      : conn_(std::move(_other.conn_)), flag_(_other.flag_) {
    30→    _other.flag_.reset();
    31→  }
    32→
    33→  ~Session() {
    34→    if (flag_) {
    35→      flag_->clear();
    36→    }
    37→  }
    38→
    39→  Result<Nothing> begin_transaction() { return conn_->begin_transaction(); }
    40→
    41→  Result<Nothing> commit() { return conn_->commit(); }
    42→
    43→  Result<Nothing> execute(const std::string& _sql) {
    44→    return conn_->execute(_sql);
    45→  }
    46→
    47→  template <class ItBegin, class ItEnd>
    48→  Result<Nothing> insert(const dynamic::Insert& _stmt, ItBegin _begin,
    49→                         ItEnd _end) {
    50→    return conn_->insert(_stmt, _begin, _end);
    51→  }
    52→
    53→  Session& operator=(const Session& _other) = delete;
    54→
    55→  Session& operator=(Session&& _other) noexcept {
    56→    if (this == &_other) {
    57→      return *this;
