     1→#ifndef SQLGEN_ITERATOR_HPP_
     2→#define SQLGEN_ITERATOR_HPP_
     3→
     4→#include <iterator>
     5→#include <memory>
     6→#include <ranges>
     7→
     8→#include "IteratorBase.hpp"
     9→#include "Ref.hpp"
    10→#include "Result.hpp"
    11→#include "internal/batch_size.hpp"
    12→#include "internal/collect/vector.hpp"
    13→#include "internal/from_str_vec.hpp"
    14→
    15→namespace sqlgen {
    16→
    17→/// An input_iterator that returns the underlying type.
    18→template <class T>
    19→class Iterator {
    20→ public:
    21→  using difference_type = std::ptrdiff_t;
    22→  using value_type = Result<T>;
    23→
    24→  struct End {
    25→    bool operator==(const Iterator<T>& _it) const noexcept {
    26→      return _it == *this;
    27→    }
    28→
    29→    bool operator!=(const Iterator<T>& _it) const noexcept {
    30→      return _it != *this;
    31→    }
    32→  };
    33→
    34→  Iterator(const Ref<IteratorBase>& _it)
    35→      : current_batch_(get_next_batch(_it)), it_(_it), ix_(0) {}
    36→
    37→  ~Iterator() = default;
    38→
    39→  Result<T>& operator*() const noexcept { return (*current_batch_)[ix_]; }
    40→
    41→  Result<T>* operator->() const noexcept { return &(*current_batch_)[ix_]; }
    42→
    43→  bool operator==(const End&) const noexcept {
    44→    return ix_ >= current_batch_->size();
    45→  }
    46→
    47→  bool operator!=(const End& _end) const noexcept { return !(*this == _end); }
    48→
    49→  Iterator<T>& operator++() noexcept {
    50→    ++ix_;
    51→    if (ix_ >= current_batch_->size() && !it_->end()) {
    52→      current_batch_ = get_next_batch(it_);
    53→      ix_ = 0;
    54→    }
    55→    return *this;
    56→  }
    57→
    58→  void operator++(int) noexcept { ++*this; }
    59→
    60→ private:
    61→  static Ref<std::vector<Result<T>>> get_next_batch(
    62→      const Ref<IteratorBase>& _it) noexcept {
    63→    using namespace std::ranges::views;
    64→    return _it->next(SQLGEN_BATCH_SIZE)
    65→        .transform([](auto str_vec) {
    66→          return Ref<std::vector<Result<T>>>::make(internal::collect::vector(
    67→              str_vec | transform(internal::from_str_vec<T>)));
    68→        })
    69→        .value_or(Ref<std::vector<Result<T>>>());
    70→  }
    71→
    72→ private:
    73→  /// The current batch of data.
    74→  Ref<std::vector<Result<T>>> current_batch_;
    75→
    76→  /// The underlying database iterator.
    77→  Ref<IteratorBase> it_;
    78→
    79→  /// The current index in the current batch.
    80→  size_t ix_;
    81→};
    82→
    83→}  // namespace sqlgen
    84→
    85→#endif
    86→

