    20→TEST(sqlite, test_group_by) {
    21→  const auto people1 = std::vector<Person>(
    22→      {Person{
    23→           .id = 0, .first_name = "Homer", .last_name = "Simpson", .age = 45},
    24→       Person{.id = 1, .first_name = "Bart", .last_name = "Simpson", .age = 10},
    25→       Person{.id = 2, .first_name = "Lisa", .last_name = "Simpson", .age = 8},
    26→       Person{
    27→           .id = 3, .first_name = "Maggie", .last_name = "Simpson", .age = 0}});
    28→
    29→  using namespace sqlgen;
    30→  using namespace sqlgen::literals;
    31→
    32→  struct Children {
    33→    std::string last_name;
    34→    int num_children;
    35→    int num_last_names;
    36→    double avg_age;
    37→    double max_age;
    38→    double min_age;
    39→    double sum_age;
    40→  };
    41→
    42→  const auto get_children =
    43→      select_from<Person>(
    44→          "last_name"_c, avg("age"_c).as<"avg_age">(),
    45→          count().as<"num_children">(), max("age"_c).as<"max_age">(),
    46→          min("age"_c).as<"min_age">(), sum("age"_c).as<"sum_age">(),
    47→          count_distinct("last_name"_c).as<"num_last_names">()) |
    48→      where("age"_c < 18) | group_by("last_name"_c) | to<std::vector<Children>>;
    49→
    50→  const auto children = sqlite::connect()
    51→                            .and_then(drop<Person> | if_exists)
    52→                            .and_then(write(std::ref(people1)))
    53→                            .and_then(get_children)
    54→                            .value();
    55→
    56→  EXPECT_EQ(children.size(), 1);
    57→  EXPECT_EQ(children.at(0).last_name, "Simpson");
    58→  EXPECT_EQ(children.at(0).num_children, 3);
    59→  EXPECT_EQ(children.at(0).num_last_names, 1);
    60→  EXPECT_EQ(children.at(0).avg_age, 6.0);
    61→  EXPECT_EQ(children.at(0).max_age, 10.0);
    62→  EXPECT_EQ(children.at(0).min_age, 0.0);
    63→  EXPECT_EQ(children.at(0).sum_age, 18.0);
    64→}
    65→
    66→}  // namespace test_group_by
