     1→#ifndef SQLGEN_PARSING_PARSER_DEFAULT_HPP_
     2→#define SQLGEN_PARSING_PARSER_DEFAULT_HPP_
     3→
     4→#include <ranges>
     5→#include <rfl.hpp>
     6→#include <string>
     7→#include <type_traits>
     8→
     9→#include "../Result.hpp"
    10→#include "../dynamic/Type.hpp"
    11→#include "../dynamic/types.hpp"
    12→#include "../transpilation/has_reflection_method.hpp"
    13→#include "Parser_base.hpp"
    14→
    15→namespace sqlgen::parsing {
    16→
    17→template <class T>
    18→struct Parser {
    19→  using Type = std::remove_cvref_t<T>;
    20→
    21→  static Result<T> read(const std::optional<std::string>& _str) noexcept {
    22→    if constexpr (transpilation::has_reflection_method<Type>) {
    23→      return Parser<std::remove_cvref_t<typename Type::ReflectionType>>::read(
    24→                 _str)
    25→          .transform([](auto&& _t) { return Type(std::move(_t)); });
    26→
    27→    } else {
    28→      if (!_str) {
    29→        return error("NULL value encounted: Numeric value cannot be NULL.");
    30→      }
    31→
    32→      try {
    33→        if constexpr (std::is_floating_point_v<Type>) {
    34→          return static_cast<Type>(std::stod(*_str));
    35→        } else if constexpr (std::is_integral_v<Type>) {
    36→          return static_cast<Type>(std::stoll(*_str));
    37→        } else if constexpr (std::is_same_v<Type, bool>) {
    38→          return std::stoi(*_str) != 0;
    39→        } else if constexpr (std::is_enum_v<Type>) {
    40→          if (auto res = rfl::string_to_enum<Type>(*_str)) {
    41→            return Type{*res};
    42→          } else {
    43→            return error(res.error());
    44→          }
    45→        } else {
    46→          static_assert(rfl::always_false_v<Type>, "Unsupported type");
    47→        }
    48→
    49→      } catch (std::exception& e) {
    50→        return error(e.what());
    51→      }
    52→    }
    53→  }
    54→
    55→  static std::optional<std::string> write(const T& _t) noexcept {
    56→    if constexpr (transpilation::has_reflection_method<Type>) {
    57→      return Parser<std::remove_cvref_t<typename Type::ReflectionType>>::write(
    58→          _t.reflection());
    59→    } else if constexpr (std::is_enum_v<Type>) {
    60→      return rfl::enum_to_string(_t);
    61→    } else {
    62→      return std::to_string(_t);
    63→    }
    64→  }
    65→
    66→  static dynamic::Type to_type() noexcept {
    67→    if constexpr (transpilation::has_reflection_method<Type>) {
    68→      return Parser<
    69→          std::remove_cvref_t<typename Type::ReflectionType>>::to_type();
    70→
    71→    } else if constexpr (std::is_same_v<T, bool>) {
    72→      return dynamic::types::Boolean{};
    73→
    74→    } else if constexpr (std::is_integral_v<T> && std::is_signed_v<T>) {
    75→      if constexpr (sizeof(T) == 1) {
    76→        return dynamic::types::Int8{};
    77→
    78→      } else if constexpr (sizeof(T) == 2) {
    79→        return dynamic::types::Int16{};
    80→
    81→      } else if constexpr (sizeof(T) == 4) {
    82→        return dynamic::types::Int32{};
    83→
    84→      } else if constexpr (sizeof(T) == 8) {
    85→        return dynamic::types::Int64{};
    86→
    87→      } else {
    88→        static_assert(rfl::always_false_v<T>, "Unsupported signed integer.");
    89→      }
    90→
    91→    } else if constexpr (std::is_integral_v<T> && !std::is_signed_v<T>) {
    92→      if constexpr (sizeof(T) == 1) {
    93→        return dynamic::types::UInt8{};
    94→
    95→      } else if constexpr (sizeof(T) == 2) {
    96→        return dynamic::types::UInt16{};
    97→
    98→      } else if constexpr (sizeof(T) == 4) {
    99→        return dynamic::types::UInt32{};
   100→
   101→      } else if constexpr (sizeof(T) == 8) {
   102→        return dynamic::types::UInt64{};
   103→
   104→      } else {
   105→        static_assert(rfl::always_false_v<T>, "Unsupported unsigned integer.");
   106→      }
   107→
   108→    } else if constexpr (std::is_floating_point_v<T>) {
   109→      if constexpr (sizeof(T) == 4) {
   110→        return dynamic::types::Float32{};
   111→
   112→      } else if constexpr (sizeof(T) == 8) {
   113→        return dynamic::types::Float64{};
   114→
   115→      } else {
   116→        static_assert(rfl::always_false_v<T>,
   117→                      "Unsupported floating point value.");
   118→      }
   119→
   120→    } else if constexpr (std::is_enum_v<T>) {
   121→      constexpr auto values = rfl::get_enumerator_array<T>();
   122→      std::array<std::string_view, std::size(values)> enum_names{};
   123→      for (std::size_t i = 0; i < std::size(values); ++i) {
   124→        enum_names[i] = values[i].first;
   125→      }
   126→      constexpr auto org_name = rfl::internal::get_type_name_str_view<T>();
   127→      static_assert(org_name.size() < 64,
   128→                    "Enum type exceeds type level. If it's defined in a nested "
   129→                    "namespace, consider moving it up to a higher level.");
   130→      // Transform '::' to '__' to avoid postgres limitations
   131→      std::string trf_name(org_name);
   132→      std::ranges::replace(trf_name, ':', '_');
   133→      return sqlgen::dynamic::types::Enum{
   134→          std::move(trf_name),
   135→          std::vector<std::string>(enum_names.begin(), enum_names.end())};
   136→    } else {
   137→      static_assert(rfl::always_false_v<T>, "Unsupported type.");
   138→    }
   139→  }
   140→};
   141→
   142→}  // namespace sqlgen::parsing
   143→
   144→#endif
   145→

