    11→
    12→namespace sqlgen::sqlite {
    13→
    14→std::string aggregation_to_sql(
    15→    const dynamic::Aggregation& _aggregation) noexcept;
    16→
    17→std::string column_or_value_to_sql(const dynamic::ColumnOrValue& _col) noexcept;
    18→
    19→std::string column_to_sql_definition(const dynamic::Column& _col) noexcept;
    20→
    21→std::string condition_to_sql(const dynamic::Condition& _cond) noexcept;
    22→
    23→template <class ConditionType>
    24→std::string condition_to_sql_impl(const ConditionType& _condition) noexcept;
    25→
    26→std::string create_index_to_sql(const dynamic::CreateIndex& _stmt) noexcept;
    27→
    28→std::string create_table_to_sql(const dynamic::CreateTable& _stmt) noexcept;
    29→
    30→std::string create_as_to_sql(const dynamic::CreateAs& _stmt) noexcept;
    31→
    32→std::string delete_from_to_sql(const dynamic::DeleteFrom& _stmt) noexcept;
    33→
    34→std::string drop_to_sql(const dynamic::Drop& _stmt) noexcept;
    35→
    36→std::string escape_single_quote(const std::string& _str) noexcept;
    37→
    38→std::string field_to_str(const dynamic::SelectFrom::Field& _field) noexcept;
    39→
    40→template <class InsertOrWrite>
    41→std::string insert_or_write_to_sql(const InsertOrWrite& _stmt) noexcept;
    42→
    43→std::string join_to_sql(const dynamic::Join& _stmt) noexcept;
    44→
    45→std::string operation_to_sql(const dynamic::Operation& _stmt) noexcept;
    46→
    47→std::string properties_to_sql(const dynamic::types::Properties& _p) noexcept;
    48→
    49→std::string select_from_to_sql(const dynamic::SelectFrom& _stmt) noexcept;
    50→
    51→std::string table_or_query_to_sql(
    52→    const dynamic::SelectFrom::TableOrQueryType& _table_or_query) noexcept;
    53→
    54→std::string type_to_sql(const dynamic::Type& _type) noexcept;
    55→
    56→std::string update_to_sql(const dynamic::Update& _stmt) noexcept;
    57→
    58→// ----------------------------------------------------------------------------
    59→
    60→inline std::string get_name(const dynamic::Column& _col) { return _col.name; }
    61→
    62→inline std::string wrap_in_quotes(const std::string& _name) noexcept {
    63→  return "\"" + _name + "\"";
    64→}
    65→
    66→// ----------------------------------------------------------------------------
    67→
    68→std::string aggregation_to_sql(
    69→    const dynamic::Aggregation& _aggregation) noexcept {
    70→  return _aggregation.val.visit([](const auto& _agg) -> std::string {
    71→    using Type = std::remove_cvref_t<decltype(_agg)>;
    72→    std::stringstream stream;
    73→    if constexpr (std::is_same_v<Type, dynamic::Aggregation::Avg>) {
    74→      stream << "AVG(" << operation_to_sql(*_agg.val) << ")";
    75→
    76→    } else if constexpr (std::is_same_v<Type, dynamic::Aggregation::Count>) {
    77→      const auto val =
    78→          std::string(_agg.val && _agg.distinct ? "DISTINCT " : "") +
    79→          (_agg.val ? column_or_value_to_sql(*_agg.val) : std::string("*"));
    80→      stream << "COUNT(" << val << ")";
    81→
    82→    } else if constexpr (std::is_same_v<Type, dynamic::Aggregation::Max>) {
    83→      stream << "MAX(" << operation_to_sql(*_agg.val) << ")";
    84→
    85→    } else if constexpr (std::is_same_v<Type, dynamic::Aggregation::Min>) {
    86→      stream << "MIN(" << operation_to_sql(*_agg.val) << ")";
    87→
    88→    } else if constexpr (std::is_same_v<Type, dynamic::Aggregation::Sum>) {
    89→      stream << "SUM(" << operation_to_sql(*_agg.val) << ")";
    90→
    91→    } else {
    92→      static_assert(rfl::always_false_v<Type>, "Not all cases were covered.");
    93→    }
    94→    return stream.str();
    95→  });
    96→}
    97→
    98→std::string pad_with_zeros(const std::string& _str,
    99→                           const size_t _expected_length) {
   100→  if (_str.size() < _expected_length) {
   101→    return std::string(_expected_length - _str.size(), '0') + _str;
   102→  } else {
   103→    return _str;
   104→  }
   105→}
   106→
   107→std::string column_or_value_to_sql(
   108→    const dynamic::ColumnOrValue& _col) noexcept {
   109→  const auto handle_value = [](const auto& _v) -> std::string {
   110→    using Type = std::remove_cvref_t<decltype(_v)>;
   111→    if constexpr (std::is_same_v<Type, dynamic::String>) {
   112→      return "'" + escape_single_quote(_v.val) + "'";
   113→
   114→    } else if constexpr (std::is_same_v<Type, dynamic::Duration>) {
   115→      const auto prefix = std::string("'") + (_v.val >= 0 ? "+" : "-");
   116→      const auto val = std::abs(_v.val);
   117→      switch (_v.unit) {
   118→        case dynamic::TimeUnit::milliseconds: {
   119→          const auto h = (val / 3600000);
   120→          const auto m = (val / 60000) % 60;
   121→          const auto s = (val / 1000) % 60;
   122→          const auto ms = val % 1000;
   123→          return prefix + pad_with_zeros(std::to_string(h), 2) + ":" +
   124→                 pad_with_zeros(std::to_string(m), 2) + ":" +
   125→                 pad_with_zeros(std::to_string(s), 2) + "." +
   126→                 pad_with_zeros(std::to_string(ms), 3) + "'";
   127→        }
   128→
   129→        case dynamic::TimeUnit::weeks:
   130→          return prefix + std::to_string(val * 7) + " days'";
   131→
   132→        default:
   133→          return prefix + std::to_string(val) + " " +
   134→                 rfl::enum_to_string(_v.unit) + "'";
   135→      }
   136→
   137→    } else if constexpr (std::is_same_v<Type, dynamic::Timestamp>) {
   138→      return std::to_string(_v.seconds_since_unix);
   139→
   140→    } else {
   141→      return std::to_string(_v.val);
   142→    }
   143→  };
   144→
   145→  return _col.visit([&](const auto& _c) -> std::string {
   146→    using Type = std::remove_cvref_t<decltype(_c)>;
   147→    if constexpr (std::is_same_v<Type, dynamic::Column>) {
   148→      if (_c.alias) {
   149→        return *_c.alias + "." + wrap_in_quotes(_c.name);
   150→      } else {
   151→        return wrap_in_quotes(_c.name);
   152→      }
   153→    } else {
   154→      return _c.val.visit(handle_value);
   155→    }
   156→  });
   157→}
