   470→std::string operation_to_sql(const dynamic::Operation& _stmt) noexcept {
   471→  using namespace std::ranges::views;
   472→  return _stmt.val.visit([](const auto& _s) -> std::string {
   473→    using Type = std::remove_cvref_t<decltype(_s)>;
   474→
   475→    std::stringstream stream;
   476→
   477→    if constexpr (std::is_same_v<Type, dynamic::Operation::Abs>) {
   478→      stream << "abs(" << operation_to_sql(*_s.op1) << ")";
   479→
   480→    } else if constexpr (std::is_same_v<Type, dynamic::Aggregation>) {
   481→      stream << aggregation_to_sql(_s);
   482→
   483→    } else if constexpr (std::is_same_v<Type, dynamic::Operation::Cast>) {
   484→      stream << "cast(" << operation_to_sql(*_s.op1) << " as "
   485→             << type_to_sql(_s.target_type) << ")";
   486→
   487→    } else if constexpr (std::is_same_v<Type, dynamic::Operation::Coalesce>) {
   488→      stream << "coalesce("
   489→             << internal::strings::join(
   490→                    ", ", internal::collect::vector(
   491→                              _s.ops | transform([](const auto& _op) {
   492→                                return operation_to_sql(*_op);
   493→                              })))
   494→             << ")";
   495→
   496→    } else if constexpr (std::is_same_v<Type, dynamic::Operation::Ceil>) {
   497→      stream << "ceil(" << operation_to_sql(*_s.op1) << ")";
   498→
   499→    } else if constexpr (std::is_same_v<Type, dynamic::Column>) {
   500→      stream << column_or_value_to_sql(_s);
   501→
   502→    } else if constexpr (std::is_same_v<Type, dynamic::Operation::Concat>) {
   503→      stream << "("
   504→             << internal::strings::join(
   505→                    " || ", internal::collect::vector(
   506→                                _s.ops | transform([](const auto& _op) {
   507→                                  return operation_to_sql(*_op);
   508→                                })))
   509→             << ")";
   510→
   511→    } else if constexpr (std::is_same_v<Type, dynamic::Operation::Cos>) {
   512→      stream << "cos(" << operation_to_sql(*_s.op1) << ")";
   513→
   514→    } else if constexpr (std::is_same_v<Type, dynamic::Operation::Day>) {
   515→      stream << "cast(strftime('%d', " << operation_to_sql(*_s.op1)
   516→             << ") as INT)";
   517→
   518→    } else if constexpr (std::is_same_v<Type,
   519→                                        dynamic::Operation::DaysBetween>) {
   520→      stream << "julianday(" << operation_to_sql(*_s.op2) << ") - julianday("
   521→             << operation_to_sql(*_s.op1) << ")";
   522→
   523→    } else if constexpr (std::is_same_v<Type,
   524→                                        dynamic::Operation::DatePlusDuration>) {
   525→      stream << "datetime(" << operation_to_sql(*_s.date) << ", "
   526→             << internal::strings::join(
   527→                    ", ",
   528→                    internal::collect::vector(
   529→                        _s.durations | transform([](const auto& _d) {
   530→                          return column_or_value_to_sql(dynamic::Value{_d});
   531→                        })))
   532→             << ")";
   533→
   534→    } else if constexpr (std::is_same_v<Type, dynamic::Operation::Divides>) {
   535→      stream << "(" << operation_to_sql(*_s.op1) << ") / ("
   536→             << operation_to_sql(*_s.op2) << ")";
   537→
   538→    } else if constexpr (std::is_same_v<Type, dynamic::Operation::Exp>) {
   539→      stream << "exp(" << operation_to_sql(*_s.op1) << ")";
   540→
   541→    } else if constexpr (std::is_same_v<Type, dynamic::Operation::Floor>) {
   542→      stream << "floor(" << operation_to_sql(*_s.op1) << ")";
   543→
   544→    } else if constexpr (std::is_same_v<Type, dynamic::Operation::Hour>) {
   545→      stream << "cast(strftime('%H', " << operation_to_sql(*_s.op1)
   546→             << ") as INT)";
   547→
   548→    } else if constexpr (std::is_same_v<Type, dynamic::Operation::Length>) {
