   642→std::string properties_to_sql(const dynamic::types::Properties& _p) noexcept {
   643→  return [&]() -> std::string {
   644→    return std::string(_p.primary ? " PRIMARY KEY" : "") +
   645→           std::string(_p.auto_incr ? " AUTOINCREMENT" : "") +
   646→           std::string(_p.nullable ? "" : " NOT NULL") +
   647→           std::string(_p.unique ? " UNIQUE" : "");
   648→  }() + [&]() -> std::string {
   649→    if (!_p.foreign_key_reference) {
   650→      return "";
   651→    }
   652→    const auto& ref = *_p.foreign_key_reference;
   653→    return " REFERENCES " + wrap_in_quotes(ref.table) + "(" +
   654→           wrap_in_quotes(ref.column) + ")";
   655→  }();
   656→}
