    19→
    20→namespace sqlgen {
    21→
    22→template <rfl::internal::StringLiteral _name,
    23→          rfl::internal::StringLiteral _alias = "">
    24→struct Col {
    25→  using ColType = transpilation::Col<_name, _alias>;
    26→  using Name = rfl::Literal<_name>;
    27→  using Alias = rfl::Literal<_alias>;
    28→
    29→  template <rfl::internal::StringLiteral _new_name>
    30→  auto as() const noexcept {
    31→    return transpilation::As<transpilation::Col<_name, _alias>, _new_name>{
    32→        .val = transpilation::Col<_name, _alias>{}};
    33→  }
    34→
    35→  /// Signals to order_by that this column is to be sorted in descending order.
    36→  auto desc() const noexcept {
    37→    return transpilation::Desc<transpilation::Col<_name, _alias>>{};
    38→  }
    39→
    40→  /// Returns the column name.
    41→  std::string name() const noexcept { return Name().str(); }
    42→
    43→  /// Returns an IN condition.
    44→  template <class... Ts>
    45→  auto in(const Ts&... _ts) const noexcept {
    46→    return transpilation::make_condition(transpilation::conditions::in(
    47→        transpilation::Col<_name, _alias>{}, _ts...));
    48→  }
    49→
    50→  /// Returns an IS NULL condition.
    51→  auto is_null() const noexcept {
    52→    return transpilation::make_condition(transpilation::conditions::is_null(
    53→        transpilation::Col<_name, _alias>{}));
    54→  }
    55→
    56→  /// Returns a IS NOT NULL condition.
    57→  auto is_not_null() const noexcept {
    58→    return transpilation::make_condition(transpilation::conditions::is_not_null(
    59→        transpilation::Col<_name, _alias>{}));
    60→  }
    61→
    62→  /// Returns a LIKE condition.
    63→  auto like(const std::string& _pattern) const noexcept {
    64→    return transpilation::make_condition(transpilation::conditions::like(
    65→        transpilation::Col<_name, _alias>{}, _pattern));
    66→  }
    67→
    68→  /// Returns a NOT LIKE condition.
    69→  auto not_like(const std::string& _pattern) const noexcept {
    70→    return transpilation::make_condition(transpilation::conditions::not_like(
    71→        transpilation::Col<_name, _alias>{}, _pattern));
    72→  }
    73→
    74→  /// Returns a NOT IN condition.
    75→  template <class... Ts>
    76→  auto not_in(const Ts&... _ts) const noexcept {
    77→    return transpilation::make_condition(transpilation::conditions::not_in(
    78→        transpilation::Col<_name, _alias>{}, _ts...));
    79→  }
    80→
    81→  /// Returns a SET clause in an UPDATE statement.
    82→  template <class T>
    83→  auto set(const T& _to) const noexcept {
    84→    return transpilation::Set<transpilation::Col<_name, _alias>,
    85→                              std::remove_cvref_t<T>>{.to = _to};
    86→  }
    87→
    88→  /// Returns a SET clause in an UPDATE statement.
    89→  template <rfl::internal::StringLiteral _other_name,
    90→            rfl::internal::StringLiteral _other_alias>
    91→  auto set(const Col<_other_name, _other_alias>& _to) const noexcept {
    92→    return transpilation::Set<transpilation::Col<_name, _alias>,
    93→                              transpilation::Col<_other_name, _other_alias>>{
    94→        .to = transpilation::Col<_other_name, _other_alias>{}};
    95→  }
    96→
    97→  /// Returns a SET clause in an UPDATE statement.
    98→  auto set(const char* _to) const noexcept {
    99→    return transpilation::Set<transpilation::Col<_name, _alias>, std::string>{
   100→        .to = _to};
   101→  }
   102→
   103→  template <class T>
   104→  friend auto operator==(const Col&, const T& _t) {
   105→    return transpilation::make_condition(transpilation::conditions::equal(
   106→        transpilation::Col<_name, _alias>{},
   107→        transpilation::to_transpilation_type(_t)));
   108→  }
   109→
   110→  template <class T>
   111→  friend auto operator!=(const Col&, const T& _t) {
   112→    return transpilation::make_condition(transpilation::conditions::not_equal(
   113→        transpilation::Col<_name, _alias>{},
   114→        transpilation::to_transpilation_type(_t)));
   115→  }
   116→
   117→  template <class T>
   118→  friend auto operator<(const Col&, const T& _t) {
   119→    return transpilation::make_condition(transpilation::conditions::lesser_than(
   120→        transpilation::Col<_name, _alias>{},
   121→        transpilation::to_transpilation_type(_t)));
   122→  }
   123→
   124→  template <class T>
   125→  friend auto operator<=(const Col&, const T& _t) {
   126→    return transpilation::make_condition(
   127→        transpilation::conditions::lesser_equal(
   128→            transpilation::Col<_name, _alias>{},
   129→            transpilation::to_transpilation_type(_t)));
   130→  }
