     9→namespace sqlgen {
    10→
    11→template <size_t _size>
    12→class Varchar {
    13→ public:
    14→  using ReflectionType = std::string;
    15→
    16→  static constexpr size_t size_ = _size;
    17→
    18→  Varchar() : value_("") {}
    19→
    20→  Varchar(const std::string& _value) : value_(check_size(_value)) {}
    21→
    22→  Varchar(const char* _value) : value_(check_size(_value)) {}
    23→
    24→  Varchar(Varchar<_size>&& _other) noexcept = default;
    25→
    26→  Varchar(const Varchar<_size>& _other) = default;
    27→
    28→  template <size_t _other_size>
    29→  Varchar(const Varchar<_other_size>& _other)
    30→      : value_(check_size(_other.get())) {}
    31→
    32→  template <size_t _other_size>
    33→  Varchar(Varchar<_other_size>&& _other) : value_(check_size(_other.get())) {}
    34→
    35→  ~Varchar() = default;
    36→
    37→  static Result<Varchar<size_>> make(const std::string& _value) noexcept {
    38→    try {
    39→      return Varchar<size_>(_value);
    40→    } catch (std::exception& e) {
    41→      return error(e.what());
    42→    }
    43→  }
    44→
    45→  /// Returns the underlying object.
    46→  const ReflectionType& get() const { return value_; }
    47→
    48→  /// Returns the underlying object.
    49→  const ReflectionType& operator()() const { return value_; }
    50→
    51→  /// Assigns the underlying object.
    52→  auto& operator=(const char* _value) {
    53→    value_ = check_size(_value);
    54→    return *this;
    55→  }
    56→
    57→  /// Assigns the underlying object.
    58→  auto& operator=(const std::string& _value) {
    59→    value_ = check_size(_value);
    60→    return *this;
    61→  }
    62→
    63→  /// Assigns the underlying object.
    64→  Varchar<_size>& operator=(const Varchar<_size>& _other) = default;
    65→
    66→  /// Assigns the underlying object.
    67→  Varchar<_size>& operator=(Varchar<_size>&& _other) = default;
    68→
    69→  /// Assigns the underlying object.
    70→  template <size_t _other_size>
    71→  auto& operator=(const Varchar<_other_size>& _other) {
    72→    value_ = check_size(_other.get());
    73→    return *this;
    74→  }
    75→
    76→  /// Necessary for the automated transpilation to work.
    77→  const std::string& reflection() const { return value_; }
    78→
    79→  static constexpr size_t size() { return size_; }
    80→
    81→  /// Returns the underlying object.
    82→  const std::string& value() const { return value_; }
    83→
    84→ private:
    85→  static std::string check_size(const std::string& _str) {
    86→    if (_str.size() > size_) {
    87→      throw std::runtime_error(
    88→          "String '" + _str + "' too long: " + std::to_string(_str.size()) +
    89→          " exceeds the maximum length of " + std::to_string(size_) + ".");
    90→    }
    91→    return _str;
    92→  }
    93→
    94→ private:
    95→  /// The underlying value.
    96→  std::string value_;
    97→};
    98→
    99→}  // namespace sqlgen
