     9→namespace test_join {
    10→
    11→struct Person {
    12→  sqlgen::PrimaryKey<uint32_t> id;
    13→  std::string first_name;
    14→  std::string last_name;
    15→  double age;
    16→};
    17→
    18→TEST(sqlite, test_join) {
    19→  const auto people1 = std::vector<Person>(
    20→      {Person{
    21→           .id = 0, .first_name = "Homer", .last_name = "Simpson", .age = 45},
    22→       Person{.id = 1, .first_name = "Bart", .last_name = "Simpson", .age = 10},
    23→       Person{.id = 2, .first_name = "Lisa", .last_name = "Simpson", .age = 8},
    24→       Person{
    25→           .id = 3, .first_name = "Maggie", .last_name = "Simpson", .age = 0}});
    26→
    27→  using namespace sqlgen;
    28→  using namespace sqlgen::literals;
    29→
    30→  const auto get_people =
    31→      select_from<Person, "t1">(
    32→          "id"_t1 | as<"id">, "first_name"_t1 | as<"first_name">,
    33→          "last_name"_t2 | as<"last_name">, "age"_t2 | as<"age">) |
    34→      inner_join<Person, "t2">("id"_t1 == "id"_t2) | order_by("id"_t1) |
    35→      to<std::vector<Person>>;
    36→
    37→  const auto people = sqlite::connect()
    38→                          .and_then(write(std::ref(people1)))
    39→                          .and_then(get_people)
    40→                          .value();
    41→
    42→  const std::string expected_query =
    43→      R"(SELECT t1."id" AS "id", t1."first_name" AS "first_name", t2."last_name" AS "last_name", t2."age" AS "age" FROM "Person" t1 INNER JOIN "Person" t2 ON t1."id" = t2."id" ORDER BY t1."id")";
    44→  const std::string expected =
    45→      R"([{"id":0,"first_name":"Homer","last_name":"Simpson","age":45.0},{"id":1,"first_name":"Bart","last_name":"Simpson","age":10.0},{"id":2,"first_name":"Lisa","last_name":"Simpson","age":8.0},{"id":3,"first_name":"Maggie","last_name":"Simpson","age":0.0}])";
    46→
    47→  EXPECT_EQ(sqlite::to_sql(get_people), expected_query);
    48→  EXPECT_EQ(rfl::json::write(people), expected);
    49→}
    50→
    51→}  // namespace test_join
