   103→
   104→  template <class T>
   105→  friend auto operator-(const Operation& _op1, const T& _op2) noexcept {
   106→    if constexpr (is_duration_v<T>) {
   107→      using DurationType = std::remove_cvref_t<T>;
   108→      return _op1 + DurationType(_op2.count() * (-1));
   109→
   110→    } else {
   111→      using OtherType = typename transpilation::ToTranspilationType<
   112→          std::remove_cvref_t<T>>::Type;
   113→
   114→      return Operation<Operator::minus, Operation, OtherType>{
   115→          .operand1 = _op1, .operand2 = to_transpilation_type(_op2)};
   116→    }
   117→  }
   118→
   119→  template <class T>
   120→  friend auto operator%(const Operation& _op1, const T& _op2) noexcept {
   121→    using OtherType = typename transpilation::ToTranspilationType<
   122→        std::remove_cvref_t<T>>::Type;
   123→
   124→    return Operation<Operator::mod, Operation, OtherType>{
   125→        .operand1 = _op1, .operand2 = to_transpilation_type(_op2)};
   126→  }
   127→
   128→  template <class T>
   129→  friend auto operator*(const Operation& _op1, const T& _op2) noexcept {
   130→    using OtherType = typename transpilation::ToTranspilationType<
   131→        std::remove_cvref_t<T>>::Type;
   132→
   133→    return Operation<Operator::multiplies, Operation, OtherType>{
   134→        .operand1 = _op1, .operand2 = to_transpilation_type(_op2)};
   135→  }
   136→
   137→  template <class T>
   138→  friend auto operator+(const Operation& _op1, const T& _op2) noexcept {
   139→    if constexpr (is_duration_v<T>) {
   140→      if constexpr (Operation::op == Operator::date_plus_duration) {
   141→        using DurationType = std::remove_cvref_t<T>;
   142→        const auto op2 =
   143→            rfl::tuple_cat(_op1.operand2, rfl::Tuple<DurationType>(_op2));
   144→        using Op2Type = std::remove_cvref_t<decltype(op2)>;
   145→        return transpilation::Operation<
   146→            transpilation::Operator::date_plus_duration, Operand1Type, Op2Type>{
   147→            .operand1 = _op1.operand1, .operand2 = op2};
   148→
   149→      } else {
   150→        using DurationType = std::remove_cvref_t<T>;
   151→        return Operation<Operator::date_plus_duration, Operation,
   152→                         rfl::Tuple<DurationType>>{
   153→            .operand1 = _op1, .operand2 = rfl::Tuple<DurationType>(_op2)};
   154→      }
   155→
   156→    } else {
   157→      using OtherType = typename transpilation::ToTranspilationType<
   158→          std::remove_cvref_t<T>>::Type;
   159→
   160→      return Operation<Operator::plus, Operation, OtherType>{
   161→          .operand1 = _op1, .operand2 = to_transpilation_type(_op2)};
