    12→namespace sqlgen {
    13→
    14→template <class ValueType, class SetsType, class WhereType, class Connection>
    15→  requires is_connection<Connection>
    16→Result<Ref<Connection>> update_impl(const Ref<Connection>& _conn,
    17→                                    const SetsType& _sets,
    18→                                    const WhereType& _where) {
    19→  const auto query =
    20→      transpilation::to_update<ValueType, SetsType, WhereType>(_sets, _where);
    21→  return _conn->execute(_conn->to_sql(query)).transform([&](const auto&) {
    22→    return _conn;
    23→  });
    24→}
    25→
    26→template <class ValueType, class SetsType, class WhereType, class Connection>
    27→  requires is_connection<Connection>
    28→Result<Ref<Connection>> update_impl(const Result<Ref<Connection>>& _res,
    29→                                    const SetsType& _sets,
    30→                                    const WhereType& _where) {
    31→  return _res.and_then([&](const auto& _conn) {
    32→    return update_impl<ValueType, SetsType, WhereType>(_conn, _sets, _where);
    33→  });
    34→}
    35→
    36→template <class ValueType, class SetsType, class WhereType = Nothing>
    37→struct Update {
    38→  auto operator()(const auto& _conn) const {
    39→    return update_impl<ValueType, SetsType, WhereType>(_conn, sets_, where_);
    40→  }
    41→
    42→  template <class ConditionType>
    43→  friend auto operator|(const Update<ValueType, SetsType, WhereType>& _u,
    44→                        const Where<ConditionType>& _where) {
    45→    static_assert(std::is_same_v<WhereType, Nothing>,
    46→                  "You cannot call where(...) twice (but you can apply more "
    47→                  "than one condition by combining them with && or ||).");
    48→    return Update<ValueType, SetsType, ConditionType>{
    49→        .sets_ = _u.sets_, .where_ = _where.condition};
    50→  }
    51→
    52→  SetsType sets_;
    53→
    54→  WhereType where_;
    55→};
    56→
    57→template <class ValueType, class... SetsType>
    58→auto update(const SetsType&... _sets) {
    59→  static_assert(sizeof...(_sets) > 0, "You must update at least one column.");
    60→  using TupleType = rfl::Tuple<std::remove_cvref_t<SetsType>...>;
    61→  return Update<ValueType, TupleType>{.sets_ = TupleType(_sets...)};
    62→};
    63→
    64→}  // namespace sqlgen
