   301→namespace transpilation {
   302→
   303→template <class TableOrQueryType, class AliasType, class FieldsType,
   304→          class JoinsType, class... Args>
   305→struct ExtractTable<
   306→    SelectFrom<TableOrQueryType, AliasType, FieldsType, JoinsType, Args...>,
   307→    false> {
   308→  using TableTupleType = table_tuple_t<TableOrQueryType, AliasType, JoinsType>;
   309→  using Type = fields_to_named_tuple_t<TableTupleType, FieldsType>;
   310→};
   311→
   312→template <class TableOrQueryType, class AliasType, class FieldsType,
   313→          class JoinsType, class WhereType, class GroupByType,
   314→          class OrderByType, class LimitType, class ToType>
   315→struct ToTableOrQuery<
   316→    SelectFrom<TableOrQueryType, AliasType, FieldsType, JoinsType, WhereType,
   317→               GroupByType, OrderByType, LimitType, ToType>> {
   318→  dynamic::SelectFrom::TableOrQueryType operator()(const auto& _query) {
   319→    using TableTupleType =
   320→        table_tuple_t<TableOrQueryType, AliasType, JoinsType>;
   321→    return Ref<dynamic::SelectFrom>::make(
   322→        transpilation::to_select_from<TableTupleType, AliasType, FieldsType,
   323→                                      TableOrQueryType, JoinsType, WhereType,
   324→                                      GroupByType, OrderByType, LimitType>(
   325→            _query.fields_, _query.from_, _query.joins_, _query.where_,
   326→            _query.limit_));
   327→  }
   328→};
   329→
   330→}  // namespace transpilation
   331→
   332→template <class TableType, class... FieldTypes>
   333→inline auto select_from(const FieldTypes&... _fields) {
   334→  using FieldsType =
   335→      rfl::Tuple<typename internal::GetColType<FieldTypes>::Type...>;
   336→  return SelectFrom<transpilation::TableWrapper<TableType>, Nothing,
   337→                    FieldsType>{
   338→      .fields_ =
   339→          FieldsType(internal::GetColType<FieldTypes>::get_value(_fields)...),
   340→      .from_ = transpilation::TableWrapper<TableType>{}};
   341→}
   342→
   343→template <class TableType, rfl::internal::StringLiteral _alias,
   344→          class... FieldTypes>
   345→inline auto select_from(const FieldTypes&... _fields) {
   346→  using FieldsType =
   347→      rfl::Tuple<typename internal::GetColType<FieldTypes>::Type...>;
   348→  return SelectFrom<transpilation::TableWrapper<TableType>, Literal<_alias>,
   349→                    FieldsType>{
   350→      .fields_ =
   351→          FieldsType(internal::GetColType<FieldTypes>::get_value(_fields)...),
   352→      .from_ = transpilation::TableWrapper<TableType>{}};
   353→}
   354→
   355→template <rfl::internal::StringLiteral _alias, class QueryType,
   356→          class... FieldTypes>
   357→inline auto select_from(const QueryType& _query, const FieldTypes&... _fields) {
   358→  using FieldsType =
   359→      rfl::Tuple<typename internal::GetColType<FieldTypes>::Type...>;
   360→  return SelectFrom<QueryType, Literal<_alias>, FieldsType>{
   361→      .fields_ =
   362→          FieldsType(internal::GetColType<FieldTypes>::get_value(_fields)...),
   363→      .from_ = _query};
   364→}
   365→
   366→}  // namespace sqlgen
   367→
   368→#endif
