    25→template <class ValueType, class WhereType, class Connection>
    26→  requires is_connection<Connection>
    27→Result<Ref<Connection>> delete_from_impl(const Result<Ref<Connection>>& _res,
    28→                                         const WhereType& _where) {
    29→  return _res.and_then([&](const auto& _conn) {
    30→    return delete_from_impl<ValueType, WhereType>(_conn, _where);
    31→  });
    32→}
    33→
    34→template <class ValueType, class WhereType = Nothing>
    35→struct DeleteFrom {
    36→  auto operator()(const auto& _conn) const {
    37→    return delete_from_impl<ValueType, WhereType>(_conn, where_);
