    38→             WhereType, GroupByType, OrderByType, LimitType, ToType>> {
    39→  dynamic::Statement operator()(const auto& _create_as) const {
    40→    using TableTupleType =
    41→        transpilation::table_tuple_t<ValueType, AliasType, JoinsType>;
    42→    return to_create_as<ValueType, TableTupleType, AliasType, FieldsType,
    43→                        TableOrQueryType, JoinsType, WhereType, GroupByType,
    44→                        OrderByType, LimitType>(
    45→        _create_as.what_, _create_as.or_replace_, _create_as.if_not_exists_,
    46→        _create_as.as_.fields_, _create_as.as_.from_, _create_as.as_.joins_,
    47→        _create_as.as_.where_, _create_as.as_.limit_);
    48→  }
