    16→namespace sqlgen::transpilation {
    17→
    18→/// Simple abstraction to be used for the cast operation.
    19→template <class T>
    20→struct TypeHolder {};
    21→
    22→template <Operator _op, class _Operand1Type, class _Operand2Type = Nothing,
    23→          class _Operand3Type = Nothing>
    24→struct Operation {
    25→  static constexpr Operator op = _op;
    26→
    27→  using Operand1Type = _Operand1Type;
    28→  using Operand2Type = _Operand2Type;
    29→  using Operand3Type = _Operand3Type;
    30→
    31→  Operand1Type operand1;
    32→  Operand2Type operand2;
    33→  Operand3Type operand3;
    34→
    35→  template <rfl::internal::StringLiteral _new_name>
    36→  auto as() const noexcept {
    37→    using T = std::remove_cvref_t<decltype(*this)>;
    38→    return transpilation::As<T, _new_name>{.val = *this};
    39→  }
    40→
    41→  /// Returns an IS NULL condition.
    42→  auto is_null() const noexcept {
    43→    return make_condition(conditions::is_null(*this));
    44→  }
    45→
    46→  /// Returns a IS NOT NULL condition.
    47→  auto is_not_null() const noexcept {
    48→    return make_condition(conditions::is_not_null(*this));
    49→  }
    50→
    51→  /// Returns a LIKE condition.
    52→  auto like(const std::string& _pattern) const noexcept {
    53→    return make_condition(conditions::like(*this, _pattern));
    54→  }
    55→
    56→  /// Returns a NOT LIKE condition.
    57→  auto not_like(const std::string& _pattern) const noexcept {
    58→    return make_condition(conditions::not_like(*this, _pattern));
    59→  }
    60→
    61→  template <class T>
    62→  friend auto operator==(const Operation& _o, const T& _t) {
    63→    return make_condition(conditions::equal(_o, to_transpilation_type(_t)));
    64→  }
    65→
    66→  template <class T>
    67→  friend auto operator!=(const Operation& _o, const T& _t) {
    68→    return make_condition(conditions::not_equal(_o, to_transpilation_type(_t)));
    69→  }
    70→
    71→  template <class T>
    72→  friend auto operator<(const Operation& _o, const T& _t) {
    73→    return make_condition(
    74→        conditions::lesser_than(_o, to_transpilation_type(_t)));
    75→  }
    76→
    77→  template <class T>
    78→  friend auto operator<=(const Operation& _o, const T& _t) {
    79→    return make_condition(
    80→        conditions::lesser_equal(_o, to_transpilation_type(_t)));
    81→  }
    82→
    83→  template <class T>
    84→  friend auto operator>(const Operation& _o, const T& _t) {
    85→    return make_condition(
    86→        conditions::greater_than(_o, to_transpilation_type(_t)));
    87→  }
    88→
    89→  template <class T>
    90→  friend auto operator>=(const Operation& _o, const T& _t) {
    91→    return make_condition(
    92→        conditions::greater_equal(_o, to_transpilation_type(_t)));
    93→  }
    94→
    95→  template <class T>
    96→  friend auto operator/(const Operation& _op1, const T& _op2) noexcept {
    97→    using OtherType = typename transpilation::ToTranspilationType<
    98→        std::remove_cvref_t<T>>::Type;
    99→
   100→    return Operation<Operator::divides, Operation, OtherType>{
   101→        .operand1 = _op1, .operand2 = to_transpilation_type(_op2)};
   102→  }
   103→
   104→  template <class T>
   105→  friend auto operator-(const Operation& _op1, const T& _op2) noexcept {
   106→    if constexpr (is_duration_v<T>) {
   107→      using DurationType = std::remove_cvref_t<T>;
   108→      return _op1 + DurationType(_op2.count() * (-1));
   109→
   110→    } else {
   111→      using OtherType = typename transpilation::ToTranspilationType<
   112→          std::remove_cvref_t<T>>::Type;
   113→
   114→      return Operation<Operator::minus, Operation, OtherType>{
   115→          .operand1 = _op1, .operand2 = to_transpilation_type(_op2)};
   116→    }
   117→  }
   118→
   119→  template <class T>
   120→  friend auto operator%(const Operation& _op1, const T& _op2) noexcept {
   121→    using OtherType = typename transpilation::ToTranspilationType<
   122→        std::remove_cvref_t<T>>::Type;
   123→
   124→    return Operation<Operator::mod, Operation, OtherType>{
   125→        .operand1 = _op1, .operand2 = to_transpilation_type(_op2)};
   126→  }
   127→
   128→  template <class T>
   129→  friend auto operator*(const Operation& _op1, const T& _op2) noexcept {
   130→    using OtherType = typename transpilation::ToTranspilationType<
   131→        std::remove_cvref_t<T>>::Type;
   132→
   133→    return Operation<Operator::multiplies, Operation, OtherType>{
   134→        .operand1 = _op1, .operand2 = to_transpilation_type(_op2)};
   135→  }
   136→
   137→  template <class T>
   138→  friend auto operator+(const Operation& _op1, const T& _op2) noexcept {
   139→    if constexpr (is_duration_v<T>) {
   140→      if constexpr (Operation::op == Operator::date_plus_duration) {
   141→        using DurationType = std::remove_cvref_t<T>;
   142→        const auto op2 =
   143→            rfl::tuple_cat(_op1.operand2, rfl::Tuple<DurationType>(_op2));
   144→        using Op2Type = std::remove_cvref_t<decltype(op2)>;
   145→        return transpilation::Operation<
   146→            transpilation::Operator::date_plus_duration, Operand1Type, Op2Type>{
   147→            .operand1 = _op1.operand1, .operand2 = op2};
   148→
   149→      } else {
   150→        using DurationType = std::remove_cvref_t<T>;
   151→        return Operation<Operator::date_plus_duration, Operation,
   152→                         rfl::Tuple<DurationType>>{
   153→            .operand1 = _op1, .operand2 = rfl::Tuple<DurationType>(_op2)};
   154→      }
   155→
   156→    } else {
   157→      using OtherType = typename transpilation::ToTranspilationType<
   158→          std::remove_cvref_t<T>>::Type;
   159→
   160→      return Operation<Operator::plus, Operation, OtherType>{
   161→          .operand1 = _op1, .operand2 = to_transpilation_type(_op2)};
   162→    }
   163→  }
   164→};
   165→
   166→template <Operator _op, class _Operand1Type, class _Operand2Type>
   167→struct ToTranspilationType<Operation<_op, _Operand1Type, _Operand2Type>> {
   168→  using Type = Operation<_op, _Operand1Type, _Operand2Type>;
   169→
   170→  Type operator()(const Type& _val) const noexcept { return _val; }
   171→};
   172→
   173→}  // namespace sqlgen::transpilation
   174→
   175→#endif
