    11→#include "where.hpp"
    12→
    13→namespace sqlgen {
    14→
    15→template <class ValueType, class ColumnsType, class WhereType, class Connection>
    16→  requires is_connection<Connection>
    17→Result<Ref<Connection>> create_index_impl(const Ref<Connection>& _conn,
    18→                                          const std::string& _name,
    19→                                          const bool _unique,
    20→                                          const bool _if_not_exists,
    21→                                          const WhereType& _where) {
    22→  const auto query =
    23→      transpilation::to_create_index<ValueType, ColumnsType, WhereType>(
    24→          _name, _unique, _if_not_exists, _where);
    25→  return _conn->execute(_conn->to_sql(query)).transform([&](const auto&) {
    26→    return _conn;
    27→  });
    28→}
    29→
    30→template <class ValueType, class ColumnsType, class WhereType, class Connection>
    31→  requires is_connection<Connection>
    32→Result<Ref<Connection>> create_index_impl(const Result<Ref<Connection>>& _res,
    33→                                          const std::string& _name,
    34→                                          const bool _unique,
    35→                                          const bool _if_not_exists,
    36→                                          const WhereType& _where) {
    37→  return _res.and_then([&](const auto& _conn) {
    38→    return create_index_impl<ValueType, ColumnsType, WhereType>(
    39→        _conn, _name, _unique, _if_not_exists, _where);
    40→  });
    41→}
    42→
    43→template <rfl::internal::StringLiteral _name, class ValueType, class WhereType,
    44→          class... ColTypes>
    45→struct CreateIndex {
    46→  auto operator()(const auto& _conn) const {
    47→    return create_index_impl<
    48→        ValueType,
    49→        transpilation::columns_t<ValueType, typename ColTypes::ColType...>,
    50→        WhereType>(_conn, _name.str(), unique_, if_not_exists_, where_);
    51→  }
    52→
    53→  template <class ConditionType>
    54→  friend auto operator|(
    55→      const CreateIndex<_name, ValueType, WhereType, ColTypes...>& _c,
    56→      const Where<ConditionType>& _where) {
    57→    static_assert(std::is_same_v<WhereType, Nothing>,
    58→                  "You cannot call where(...) twice (but you can apply more "
    59→                  "than one condition by combining them with && or ||).");
    60→    return CreateIndex<_name, ValueType, ConditionType, ColTypes...>{
    61→        .unique_ = _c.unique_,
    62→        .if_not_exists_ = _c.if_not_exists_,
    63→        .where_ = _where.condition};
    64→  }
    65→
    66→  bool unique_ = false;
    67→  bool if_not_exists_ = false;
    68→
    69→  WhereType where_;
    70→};
    71→
    72→template <rfl::internal::StringLiteral _name, class ValueType,
    73→          class... ColTypes>
    74→auto create_index(const ColTypes&...) {
    75→  return CreateIndex<_name, ValueType, Nothing, ColTypes...>{
    76→      .unique_ = false, .if_not_exists_ = false};
    77→}
    78→
    79→template <rfl::internal::StringLiteral _name, class ValueType,
    80→          class... ColTypes>
    81→auto create_unique_index(const ColTypes&...) {
    82→  return CreateIndex<_name, ValueType, Nothing, ColTypes...>{
    83→      .unique_ = true, .if_not_exists_ = false};
    84→}
    85→
    86→};  // namespace sqlgen
    87→
    88→#endif
    89→
    90→

