     5→
     6→#include "conditions.hpp"
     7→
     8→namespace sqlgen::transpilation {
     9→
    10→template <class _ConditionType>
    11→struct Condition {
    12→  using ConditionType = _ConditionType;
    13→  ConditionType condition;
    14→
    15→  auto operator!() {
    16→    return make_condition(conditions::Not<_ConditionType>{.cond = condition});
    17→  }
    18→
    19→  template <class C2>
    20→  friend auto operator&&(const Condition& _cond1, const Condition<C2>& _cond2) {
    21→    return make_condition(conditions::And<_ConditionType, C2>{
    22→        .cond1 = _cond1.condition, .cond2 = _cond2.condition});
    23→  }
    24→
    25→  template <class C2>
    26→  friend auto operator||(const Condition& _cond1, const Condition<C2>& _cond2) {
    27→    return make_condition(conditions::Or<_ConditionType, C2>{
    28→        .cond1 = _cond1.condition, .cond2 = _cond2.condition});
    29→  }
    30→};
    31→
    32→template <class T>
    33→auto make_condition(T&& _t) {
    34→  return Condition<std::remove_cvref_t<T>>{.condition = _t};
    35→}
    36→
    37→}  // namespace sqlgen::transpilation
    38→
    39→#endif
