    16→template <>
    17→struct ToOrderBy<Nothing> {
    18→  std::optional<dynamic::OrderBy> operator()() const { return std::nullopt; }
    19→};
    20→
    21→template <class... Wrappers>
    22→struct ToOrderBy<OrderBy<Wrappers...>> {
    23→  template <class W>
    24→  dynamic::Wrapper to_wrapper() const {
    25→    using Alias = typename W::ColType::Alias;
