    31→  }
    32→
    33→  std::optional<dynamic::OrderBy> operator()() const {
    34→    const auto columns =
    35→        std::vector<dynamic::Wrapper>({to_wrapper<Wrappers>()...});
    36→    return dynamic::OrderBy{.columns = columns};
    37→  }
    38→};
