    17→
    18→template <class T>
    19→class is_ptr<std::shared_ptr<T>> : public std::true_type {};
    20→
    21→template <class T>
    22→class is_ptr<std::unique_ptr<T>> : public std::true_type {};
    23→
    24→template <class T>
    25→class is_optional;
    26→
