     7→namespace sqlgen::transpilation {
     8→
     9→namespace internal {
    10→
    11→inline std::string remove_namespaces(const std::string& _str) {
    12→  const auto pos = _str.find_last_of(':');
    13→  if (pos == std::string::npos) {
    14→    return _str;
    15→  }
    16→  return _str.substr(pos + 1);
    17→}
    18→
    19→}  // namespace internal
    20→
    21→template <class T>
    22→std::string get_tablename() noexcept {
    23→  using Type = std::remove_cvref_t<T>;
    24→
    25→  constexpr bool has_tablename = requires {
    26→    { Type::tablename } -> std::convertible_to<std::string>;
    27→  };
    28→
    29→  constexpr bool has_viewname = requires {
    30→    { Type::viewname } -> std::convertible_to<std::string>;
    31→  };
    32→
    33→  if constexpr (has_tablename) {
    34→    static_assert(
    35→        !has_viewname,
    36→        "A struct can either have a tablename or a viewname, but not both.");
    37→    return std::string(Type::tablename);
    38→
    39→  } else if constexpr (has_viewname) {
    40→    return std::string(Type::viewname);
    41→
    42→  } else {
    43→    return internal::remove_namespaces(rfl::type_name_t<Type>().str());
    44→  }
    45→}
    46→
    47→}  // namespace sqlgen::transpilation
    48→
