    19→template <class ValueType, class TableOrQueryType, class AliasType,
    20→          class FieldsType, class JoinsType, class WhereType, class GroupByType,
    21→          class OrderByType, class LimitType, class ToType, class Connection>
    22→  requires is_connection<Connection>
    23→Result<Ref<Connection>> create_as_impl(
    24→    const Ref<Connection>& _conn, const dynamic::CreateAs::What _what,
    25→    const SelectFrom<TableOrQueryType, AliasType, FieldsType, JoinsType,
    26→                     WhereType, GroupByType, OrderByType, LimitType, ToType>&
    27→        _as,
    28→    const bool _or_replace, const bool _if_not_exists) {
    29→  using TableTupleType =
    30→      transpilation::table_tuple_t<TableOrQueryType, AliasType, JoinsType>;
    31→
    32→  const auto query = transpilation::to_create_as<
    33→      ValueType, TableTupleType, AliasType, FieldsType, TableOrQueryType,
    34→      JoinsType, WhereType, GroupByType, OrderByType, LimitType>(
    35→      _what, _or_replace, _if_not_exists, _as.fields_, _as.from_, _as.joins_,
    36→      _as.where_, _as.limit_);
    37→
    38→  return _conn->execute(_conn->to_sql(query)).transform([&](const auto&) {
    39→    return _conn;
    40→  });
    41→}
    42→
    43→template <class ValueType, class TableOrQueryType, class AliasType,
    44→          class FieldsType, class JoinsType, class WhereType, class GroupByType,
    45→          class OrderByType, class LimitType, class ToType, class Connection>
    46→  requires is_connection<Connection>
    47→Result<Ref<Connection>> create_as_impl(
    48→    const Result<Ref<Connection>>& _res, const dynamic::CreateAs::What _what,
    49→    const SelectFrom<TableOrQueryType, AliasType, FieldsType, JoinsType,
    50→                     WhereType, GroupByType, OrderByType, LimitType, ToType>&
    51→        _as,
    52→    const bool _or_replace, const bool _if_not_exists) {
    53→  return _res.and_then([&](const auto& _conn) {
    54→    return create_as_impl<ValueType>(_conn, _what, _as, _or_replace,
    55→                                     _if_not_exists);
    56→  });
    57→}
