    43→  using namespace sqlgen::literals;
    44→
    45→  struct ParentAndChild {
    46→    std::string last_name;
    47→    std::string first_name_parent;
    48→    std::string first_name_child;
    49→    double parent_age_at_birth;
    50→  };
