    23→namespace sqlgen::transpilation {
    24→
    25→template <class T, class SetType>
    26→struct ToSet;
    27→
    28→template <class T, rfl::internal::StringLiteral _name, class ToType>
    29→struct ToSet<T, Set<transpilation::Col<_name>, ToType>> {
    30→  static_assert(
    31→      all_columns_exist<T, transpilation::Col<_name>>(),
    32→      "At least one column referenced in your SET query does not exist.");
    33→  static_assert(std::is_convertible_v<underlying_t<T, Col<_name>>,
    34→                                      underlying_t<T, Value<ToType>>>,
    35→                "Must be convertible.");
    36→
    37→  dynamic::Update::Set operator()(const auto& _set) const {
    38→    return dynamic::Update::Set{
    39→        .col = dynamic::Column{.name = _name.str()},
    40→        .to = to_value(_set.to),
    41→    };
    42→  }
    43→};
    44→
    45→template <class T, rfl::internal::StringLiteral _name1,
    46→          rfl::internal::StringLiteral _name2>
    47→struct ToSet<T, Set<transpilation::Col<_name1>, transpilation::Col<_name2>>> {
    48→  static_assert(
    49→      all_columns_exist<T, transpilation::Col<_name1>>(),
    50→      "At least one column referenced in your SET query does not exist.");
    51→  static_assert(
    52→      all_columns_exist<T, transpilation::Col<_name2>>(),
    53→      "At least one column referenced in your SET query does not exist.");
    54→  static_assert(
    55→      std::is_convertible_v<underlying_t<T, transpilation::Col<_name2>>,
    56→                            underlying_t<T, transpilation::Col<_name1>>>,
    57→      "A column referenced in your SET query is not convertible to the column "
    58→      "it is being assigned to.");
    59→
    60→  dynamic::Update::Set operator()(const auto& _set) const {
    61→    return dynamic::Update::Set{
    62→        .col = dynamic::Column{.name = _name1.str()},
    63→        .to = dynamic::Column{.name = _name2.str()},
    64→    };
    65→  }
    66→};
    67→
    68→template <class T, class SetType>
    69→dynamic::Update::Set to_set(const SetType& _set) {
    70→  return ToSet<std::remove_cvref_t<T>, std::remove_cvref_t<SetType>>{}(_set);
    71→}
    72→
    73→template <class T, class SetsType>
    74→std::vector<dynamic::Update::Set> to_sets(const SetsType& _sets) {
    75→  return rfl::apply(
    76→      [](const auto&... _s) {
    77→        return std::vector<dynamic::Update::Set>({to_set<T>(_s)...});
    78→      },
    79→      _sets);
    80→}
    81→
    82→}  // namespace sqlgen::transpilation
