     1→#ifndef SQLGEN_TRANSPILATION_TO_VALUE_HPP_
     2→#define SQLGEN_TRANSPILATION_TO_VALUE_HPP_
     3→
     4→#include <rfl.hpp>
     5→#include <type_traits>
     6→
     7→#include "../dynamic/Value.hpp"
     8→#include "Value.hpp"
     9→#include "has_reflection_method.hpp"
    10→
    11→namespace sqlgen::transpilation {
    12→
    13→template <class T>
    14→dynamic::Value to_value(const T& _t) {
    15→  using Type = std::remove_cvref_t<T>;
    16→  if constexpr (std::is_floating_point_v<Type>) {
    17→    return dynamic::Value{dynamic::Float{.val = static_cast<double>(_t)}};
    18→
    19→  } else if constexpr (std::is_integral_v<Type>) {
    20→    return dynamic::Value{dynamic::Integer{.val = static_cast<int64_t>(_t)}};
    21→
    22→  } else if constexpr (std::is_convertible_v<Type, std::string>) {
    23→    return dynamic::Value{dynamic::String{.val = std::string(_t)}};
    24→
    25→  } else if constexpr (has_reflection_method<Type>) {
    26→    return to_value(_t.reflection());
    27→
    28→  } else if constexpr (std::is_enum_v<Type>) {
    29→    return dynamic::Value{dynamic::String{.val = rfl::enum_to_string(_t)}};
    30→
    31→  } else {
    32→    static_assert(rfl::always_false_v<T>, "Unsupported type");
    33→  }
    34→}
    35→
    36→}  // namespace sqlgen::transpilation
    37→
    38→#endif
