    28→Result<Ref<Connection>> drop_impl(const Result<Ref<Connection>>& _res,
    29→                                  const dynamic::Drop::What _what,
    30→                                  const bool _if_exists, const bool _cascade) {
    31→  return _res.and_then([&](const auto& _conn) {
    32→    return drop_impl<ValueType>(_conn, _what, _if_exists, _cascade);
    33→  });
    34→}
