     7→
     8→#include "Result.hpp"
     9→#include "dynamic/CreateAs.hpp"
    10→#include "is_connection.hpp"
    11→#include "select_from.hpp"
    12→#include "transpilation/extract_table_t.hpp"
    13→#include "transpilation/get_table_or_view.hpp"
    14→#include "transpilation/table_tuple_t.hpp"
    15→#include "transpilation/to_create_as.hpp"
    16→
    17→namespace sqlgen {
    18→
    19→template <class ValueType, class TableOrQueryType, class AliasType,
    20→          class FieldsType, class JoinsType, class WhereType, class GroupByType,
    21→          class OrderByType, class LimitType, class ToType, class Connection>
    22→  requires is_connection<Connection>
    23→Result<Ref<Connection>> create_as_impl(
    24→    const Ref<Connection>& _conn, const dynamic::CreateAs::What _what,
    25→    const SelectFrom<TableOrQueryType, AliasType, FieldsType, JoinsType,
    26→                     WhereType, GroupByType, OrderByType, LimitType, ToType>&
    27→        _as,
    28→    const bool _or_replace, const bool _if_not_exists) {
    29→  using TableTupleType =
    30→      transpilation::table_tuple_t<TableOrQueryType, AliasType, JoinsType>;
    31→
    32→  const auto query = transpilation::to_create_as<
    33→      ValueType, TableTupleType, AliasType, FieldsType, TableOrQueryType,
    34→      JoinsType, WhereType, GroupByType, OrderByType, LimitType>(
    35→      _what, _or_replace, _if_not_exists, _as.fields_, _as.from_, _as.joins_,
    36→      _as.where_, _as.limit_);
    37→
    38→  return _conn->execute(_conn->to_sql(query)).transform([&](const auto&) {
    39→    return _conn;
    40→  });
    41→}
    42→
    43→template <class ValueType, class TableOrQueryType, class AliasType,
    44→          class FieldsType, class JoinsType, class WhereType, class GroupByType,
    45→          class OrderByType, class LimitType, class ToType, class Connection>
    46→  requires is_connection<Connection>
    47→Result<Ref<Connection>> create_as_impl(
    48→    const Result<Ref<Connection>>& _res, const dynamic::CreateAs::What _what,
    49→    const SelectFrom<TableOrQueryType, AliasType, FieldsType, JoinsType,
    50→                     WhereType, GroupByType, OrderByType, LimitType, ToType>&
    51→        _as,
    52→    const bool _or_replace, const bool _if_not_exists) {
    53→  return _res.and_then([&](const auto& _conn) {
    54→    return create_as_impl<ValueType>(_conn, _what, _as, _or_replace,
    55→                                     _if_not_exists);
    56→  });
    57→}
    58→
    59→template <class ValueType, class TableOrQueryType, class AliasType,
    60→          class FieldsType, class JoinsType, class WhereType, class GroupByType,
    61→          class OrderByType, class LimitType, class ToType>
    62→struct CreateAs {
    63→  using As = SelectFrom<TableOrQueryType, AliasType, FieldsType, JoinsType,
    64→                        WhereType, GroupByType, OrderByType, LimitType, ToType>;
    65→
    66→  static_assert(
    67→      requires(transpilation::extract_table_t<As, false> a) {
    68→        { rfl::from_named_tuple<ValueType>(a) } -> std::same_as<ValueType>;
    69→      },
    70→      "The query inserted into create_..._as must be convertible to "
    71→      "the output struct.");
    72→
    73→  auto operator()(const auto& _conn) const {
    74→    return create_as_impl<ValueType>(_conn, what_, as_, or_replace_,
    75→                                     if_not_exists_);
    76→  }
    77→
    78→  dynamic::CreateAs::What what_;
    79→  As as_;
    80→  bool or_replace_;
    81→  bool if_not_exists_;
    82→};
    83→
    84→template <class ValueType, class... Args>
    85→inline auto create_as(const SelectFrom<Args...>& _as) {
    86→  return CreateAs<std::remove_cvref_t<ValueType>, Args...>{
    87→      .what_ = transpilation::get_table_or_view<ValueType>(),
    88→      .as_ = _as,
    89→      .or_replace_ = false,
    90→      .if_not_exists_ = false};
    91→}
    92→
    93→template <class ValueType, class... Args>
    94→inline auto create_or_replace_view_as(const SelectFrom<Args...>& _as) {
    95→  static_assert(
    96→      transpilation::get_table_or_view<ValueType>() ==
    97→          dynamic::TableOrView::view,
    98→      "Only views can be created using create_or_replace_view_as(...), "
    99→      "not tables. To declare a struct a view, "
   100→      "simply add 'static constexpr bool is_view = true;' to the struct "
   101→      "declaration.");
   102→  return CreateAs<std::remove_cvref_t<ValueType>, Args...>{
   103→      .what_ = dynamic::TableOrView::view,
   104→      .as_ = _as,
   105→      .or_replace_ = true,
   106→      .if_not_exists_ = false};
   107→}
   108→};  // namespace sqlgen
   109→
   110→#endif
