    21→    return make_condition(conditions::And<_ConditionType, C2>{
    22→        .cond1 = _cond1.condition, .cond2 = _cond2.condition});
    23→  }
    24→
    25→  template <class C2>
    26→  friend auto operator||(const Condition& _cond1, const Condition<C2>& _cond2) {
    27→    return make_condition(conditions::Or<_ConditionType, C2>{
    28→        .cond1 = _cond1.condition, .cond2 = _cond2.condition});
    29→  }
    30→};
